// API shapes for the checkpoint world (api/routers/scan.py).

export type CheckpointId = "cp1" | "cp2";
export type TrackState = "new" | "held" | "strengthened" | "weakened" | "lost";
export type SourceKind = "feedback" | "study" | "sales" | "option_list" | "research" | "web" | "reference";

export interface Checkpoint {
  id: CheckpointId;
  label: string;          // "JAN 26"
  cutoff: string;         // ISO date
  parent_id: CheckpointId | null;
  position: number;       // 1, 2
  sources: Record<SourceKind, { visible: number; new: number }>;
  acquire: { run_id: number; parent_run_id: number | null; tracks: Record<TrackState, number> } | null;
}

export interface PointsPayload {
  n: number;
  dict: { car: string[]; market: string[]; channel: string[]; engine: string[]; type: (string | null)[] };
  cols: {
    id: number[]; x: number[]; y: number[]; z: number[];
    car: number[]; market: number[]; channel: number[]; engine: number[]; type: number[];
    len: number[]; cp: number[];   // cp = checkpoint position at which the comment becomes visible
  };
}

export interface Comment {
  id: number; external_id: string; car: string; market: string; country: string; text: string;
  channel: string | null; engine: string | null; checkpoint: CheckpointId; ref: string;
  bmw_labels: { feedback_type: string | null; vfc_level2: string | null; vfc_level3: string | null }[];
}

export interface ResearchItem {
  id: number; market: string | null; region: string | null; tier: string | null; topic: string | null;
  kind: string | null; entity: string | null; published_at: string | null; headline: string;
  yoy: number | null; value: number | null; unit: string | null; pair_key: string | null; url: string | null;
  new: boolean;
}

export interface SourcesPayload {
  checkpoint: CheckpointId;
  sales: { car: string; market: string; year: number; units: number | null; is_forecast: number }[];
  study: { car: string; market: string; scale: string; n: number; z: number | null }[];
  options: { car: string; n: number }[];
  research: ResearchItem[];
  web: { n: number; new: number };
}

// The checkpoint is app-wide state: every screen reads what is visible at the current checkpoint, and every screen
// can animate the change from the previous one (the sweep). The URL (?cp=) is the source of truth so a view can be
// linked; ← / → step between checkpoints anywhere in the app.
import { createContext, useCallback, useContext, useEffect, useMemo, useRef, useState, type ReactNode } from "react";
import { useQuery } from "@tanstack/react-query";
import { useSearchParams } from "react-router-dom";
import { api } from "@/lib/api";
import type { Checkpoint, CheckpointId } from "@/lib/types";

const ORDER: CheckpointId[] = ["cp1", "cp2"];
const isCp = (v: string | null): v is CheckpointId => v === "cp1" || v === "cp2";

interface Ctx {
  cp: CheckpointId;
  from: CheckpointId;        // checkpoint before the latest switch (equals cp when settled)
  sweepId: number;           // increments on every switch; screens restart their sweep on change
  setCp: (cp: CheckpointId) => void;
  checkpoints: Checkpoint[] | undefined;
  current: Checkpoint | undefined;
  position: number;          // 1 | 2
}

const CheckpointCtx = createContext<Ctx | null>(null);

export function CheckpointProvider({ children }: { children: ReactNode }) {
  const [params, setParams] = useSearchParams();
  const urlCp = params.get("cp");
  const cp: CheckpointId = isCp(urlCp) ? urlCp : "cp2";
  const prev = useRef<CheckpointId>(cp);
  const [from, setFrom] = useState<CheckpointId>(cp);
  const [sweepId, setSweepId] = useState(0);
  const { data: checkpoints } = useQuery({ queryKey: ["checkpoints"], queryFn: () => api.get<Checkpoint[]>("/api/checkpoints") });

  useEffect(() => {
    if (prev.current !== cp) {
      setFrom(prev.current);
      setSweepId((n) => n + 1);
      prev.current = cp;
    }
  }, [cp]);

  const setCp = useCallback(
    (next: CheckpointId) => {
      setParams((p) => { const q = new URLSearchParams(p); q.set("cp", next); return q; }, { replace: true });
    },
    [setParams],
  );

  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (e.target instanceof HTMLElement && e.target.closest("input, textarea, [contenteditable]")) return;
      const i = ORDER.indexOf(cp);
      if (e.key === "ArrowRight" && i < ORDER.length - 1) setCp(ORDER[i + 1]);
      if (e.key === "ArrowLeft" && i > 0) setCp(ORDER[i - 1]);
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [cp, setCp]);

  const value = useMemo<Ctx>(() => {
    const current = checkpoints?.find((c) => c.id === cp);
    return { cp, from, sweepId, setCp, checkpoints, current, position: ORDER.indexOf(cp) + 1 };
  }, [cp, from, sweepId, setCp, checkpoints]);

  return <CheckpointCtx.Provider value={value}>{children}</CheckpointCtx.Provider>;
}

export function useCheckpoint(): Ctx {
  const c = useContext(CheckpointCtx);
  if (!c) throw new Error("useCheckpoint outside CheckpointProvider");
  return c;
}

export const CHECKPOINT_ORDER = ORDER;

// Bottom-right sweep control: the two checkpoints as nodes on one track. The later node shows what its sweep did
// to the earlier one's tracks (held / new), so "JUL builds on JAN" is visible, not just stated.
import { useCheckpoint, CHECKPOINT_ORDER } from "@/state/checkpoint";
import type { CheckpointId } from "@/lib/types";
import "./sweep.css";

const fmt = (n: number | undefined) => (n == null ? "–" : n.toLocaleString("en-US"));

export function SweepControl() {
  const { cp, setCp, checkpoints, sweepId } = useCheckpoint();
  const byId = Object.fromEntries((checkpoints ?? []).map((c) => [c.id, c]));
  const late = byId.cp2;
  return (
    <div className="sweepctl" role="radiogroup" aria-label="Checkpoint">
      <div className="sweepctl-track" data-cp={cp}>
        <span className="sweepctl-line" />
        <span className="sweepctl-fill" key={sweepId} />
        {CHECKPOINT_ORDER.map((id: CheckpointId) => (
          <button
            key={id}
            role="radio"
            aria-checked={cp === id}
            className="sweepctl-node"
            data-on={cp === id || (cp === "cp2" && id === "cp1") ? "" : undefined}
            onClick={() => setCp(id)}
          >
            <span className="sweepctl-dot" aria-hidden />
            <span className="sweepctl-name">{byId[id]?.label ?? (id === "cp1" ? "JAN 26" : "JUL 26")}</span>
          </button>
        ))}
      </div>
      <div className="sweepctl-tracks" aria-live="polite">
        {cp === "cp2" && late?.acquire ? (
          <>
            <span><i className="mark held" aria-hidden />{fmt(late.acquire.tracks.held)}<span className="label">held</span></span>
            <span><i className="mark new" aria-hidden />{fmt(late.acquire.tracks.new)}<span className="label">new</span></span>
          </>
        ) : (
          <span><i className="mark new" aria-hidden />{fmt(byId.cp1?.acquire?.tracks.new)}<span className="label">acquired</span></span>
        )}
      </div>
    </div>
  );
}

.sweepctl {
  position: fixed; right: var(--edge); bottom: calc(var(--edge) + env(safe-area-inset-bottom, 0px)); z-index: 20;
  width: 280px; padding: 16px 18px 14px; border-radius: var(--r);
  background: var(--glass); border: 1px solid var(--hair);
  backdrop-filter: blur(14px) saturate(1.2); -webkit-backdrop-filter: blur(14px) saturate(1.2);
  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.5), 0 24px 60px rgba(0, 0, 0, 0.6);
  display: grid; gap: 14px;
}
.sweepctl-track { position: relative; display: flex; justify-content: space-between; align-items: flex-start; }
.sweepctl-line, .sweepctl-fill { position: absolute; left: 6px; right: 6px; top: 6px; height: 1px; }
.sweepctl-line { background: var(--hair-2); }
.sweepctl-fill { background: var(--sweep-hi); transform-origin: 0 50%; transform: scaleX(0); transition: transform var(--sweep-ms) var(--ease); }
.sweepctl-track[data-cp="cp2"] .sweepctl-fill { transform: scaleX(1); }
.sweepctl-node { position: relative; display: grid; gap: 8px; justify-items: start; padding: 0; border-radius: 6px; }
.sweepctl-node:last-child { justify-items: end; }
.sweepctl-dot {
  width: 13px; height: 13px; border-radius: 50%; background: var(--void); border: 1px solid var(--ink-3);
  transition: background var(--med) var(--ease), border-color var(--med) var(--ease), box-shadow var(--med) var(--ease);
}
.sweepctl-node[data-on] .sweepctl-dot { background: var(--sweep-hi); border-color: var(--sweep-hi); box-shadow: 0 0 0 4px var(--sweep-wash); }
.sweepctl-node[aria-checked="false"]:hover .sweepctl-dot { border-color: var(--ink); }
.sweepctl-name { font-size: var(--t-label); font-weight: 600; letter-spacing: 0.08em; color: var(--ink-3); transition: color var(--fast); }
.sweepctl-node[aria-checked="true"] .sweepctl-name { color: var(--ink); }
.sweepctl-tracks { display: flex; gap: 18px; justify-content: flex-end; font-size: var(--t-body); font-variant-numeric: tabular-nums; }
.sweepctl-tracks > span { display: inline-flex; align-items: center; gap: 7px; }
.sweepctl-tracks .label { margin-left: 2px; }
.mark { display: inline-block; width: 8px; height: 8px; border-radius: 50%; }
.mark.held { background: var(--ink); }
.mark.new { background: transparent; box-shadow: inset 0 0 0 1.5px var(--sweep-hi); }
@media (max-width: 560px) { .sweepctl { left: 16px; right: 16px; width: auto; } }

// Geometry of the scan volume. The comment galaxy sits in the unit ball; range rings around it carry the other raw
// sources. Angles on the car rings are sectors (one per car line); the outer ring is a time ring where the angle is
// the publication date, so the sweep that reveals the second checkpoint passes the newer research in date order.

export const TAU = Math.PI * 2;

export const CARS = ["F70", "G60", "G68", "G70"] as const;
export const CAR_NAME: Record<string, string> = { F70: "1 Series", G60: "5 Series", G68: "5 Series LWB", G70: "7 Series" };
export const MARKET_NAME: Record<string, string> = { EU: "Europe", US: "USA", CN: "China", RoW: "Rest of world" };

export const R = { study: 1.42, options: 1.62, sales: 1.86, time: 2.18, labels: 2.5 } as const;

const GAP = 0.06; // radians between car sectors
export function sector(car: string): [number, number] {
  const i = Math.max(0, CARS.indexOf(car as (typeof CARS)[number]));
  const a0 = (i * TAU) / CARS.length + GAP / 2;
  return [a0, a0 + TAU / CARS.length - GAP];
}

// Time ring: Jul 2025 → Jul 2026 over 300°, starting a quarter turn back from the Jan cut-off so Jan sits at the
// viewer's right. Older items collect just before the start.
const T0 = Date.parse("2025-07-01");
const T1 = Date.parse("2026-07-31");
const SPAN = (300 / 360) * TAU;
export const TIME_START = -SPAN * ((Date.parse("2026-01-31") - T0) / (T1 - T0));
export function timeAngle(iso: string | null): number {
  const t = iso ? Date.parse(iso.length === 7 ? `${iso}-28` : iso.length === 4 ? `${iso}-12-31` : iso) : NaN;
  if (Number.isNaN(t) || t < T0) return TIME_START - 0.08;
  return TIME_START + SPAN * Math.min(1, (t - T0) / (T1 - T0));
}
export const SWEEP_START = timeAngle("2026-01-31"); // the sweep to JUL starts at the JAN cut-off

export const polar = (r: number, a: number, y = 0): [number, number, number] => [r * Math.cos(a), y, r * Math.sin(a)];

// The scan volume (react-three-fiber). One shader decides, per contact, whether the current sweep has acquired it:
// contacts known at the earlier checkpoint are held (white); contacts the current sweep acquires turn blue and flare
// as the sweep plane passes their bearing. The same rule drives the comments and the dated research on the time ring.
import { useEffect, useMemo, useRef } from "react";
import { useFrame, useThree, type ThreeEvent } from "@react-three/fiber";
import { Html, OrbitControls } from "@react-three/drei";
import * as THREE from "three";
import type { PointsPayload, SourcesPayload } from "@/lib/types";
import { CARS, CAR_NAME, R, SWEEP_START, TAU, TIME_START, polar, sector, timeAngle } from "./layout";

const VERT = /* glsl */ `
attribute float aCp; attribute float aSel; attribute float aAz; attribute float aSize; attribute float aIdx;
uniform float uCp, uFrom, uSweep, uStart, uScale, uHover, uDim;
varying vec3 vColor; varying float vAlpha;
const float TAU = 6.2831853;
void main() {
  float lo = min(uCp, uFrom), hi = max(uCp, uFrom);
  float d = mod(aAz - uStart + 2.0 * TAU, TAU) / TAU;
  float passed = step(d, uSweep);
  float vis = aCp <= lo ? 1.0 : (aCp <= hi ? (uCp > uFrom ? passed : 1.0 - passed) : 0.0);
  float flare = (uCp > uFrom && aCp > lo && aCp <= hi) ? passed * exp(-max(uSweep - d, 0.0) * 18.0) : 0.0;
  bool acquired = abs(aCp - uCp) < 0.5;
  vColor = mix(acquired ? vec3(0.32, 0.6, 1.0) : vec3(0.92, 0.94, 0.97), vec3(1.0), flare);
  float hov = abs(aIdx - uHover) < 0.5 ? 1.0 : 0.0;
  vAlpha = vis * mix(uDim, 1.0, aSel) * (acquired ? 0.92 : 0.62) + hov;
  vec4 mv = modelViewMatrix * vec4(position, 1.0);
  gl_Position = projectionMatrix * mv;
  gl_PointSize = aSize * uScale * (1.0 + flare * 2.2 + hov * 2.5) / -mv.z;
}`;
const FRAG = /* glsl */ `
varying vec3 vColor; varying float vAlpha;
void main() {
  float r = length(gl_PointCoord - 0.5);
  if (r > 0.5) discard;
  gl_FragColor = vec4(vColor, min(vAlpha, 1.0) * smoothstep(0.5, 0.28, r));
}`;

function contactMaterial(scale: number) {
  return new THREE.ShaderMaterial({
    vertexShader: VERT, fragmentShader: FRAG, transparent: true, depthWrite: false,
    uniforms: {
      uCp: { value: 2 }, uFrom: { value: 2 }, uSweep: { value: 1 }, uStart: { value: SWEEP_START },
      uScale: { value: scale }, uHover: { value: -1 }, uDim: { value: 0.06 },
    },
  });
}

/* ------------------------------------------------------------------------------------------- sweep clock */
function useSweep(mats: THREE.ShaderMaterial[], position: number, fromPosition: number, sweepId: number, onAngle: (a: number | null) => void) {
  const start = useRef<number | null>(null);
  const reduced = useMemo(() => window.matchMedia?.("(prefers-reduced-motion: reduce)").matches ?? false, []);
  useEffect(() => {
    for (const m of mats) { m.uniforms.uCp.value = position; m.uniforms.uFrom.value = fromPosition; m.uniforms.uSweep.value = reduced ? 1 : 0; }
    start.current = reduced || position === fromPosition ? null : performance.now();
  }, [sweepId]); // eslint-disable-line react-hooks/exhaustive-deps
  useFrame(() => {
    if (start.current == null) { onAngle(null); return; }
    const t = Math.min(1, (performance.now() - start.current) / 2200);
    const e = 1 - Math.pow(1 - t, 3);
    for (const m of mats) m.uniforms.uSweep.value = e;
    onAngle(t < 1 ? SWEEP_START + e * TAU : null);
    if (t >= 1) { start.current = null; for (const m of mats) m.uniforms.uFrom.value = m.uniforms.uCp.value; }
  });
}

/* ------------------------------------------------------------------------------------------- comments */
interface SceneProps {
  points: PointsPayload;
  sources: SourcesPayload | undefined;
  mask: Uint8Array;            // 1 = matches the current key filter
  position: number; fromPosition: number; sweepId: number;
  hover: number | null;
  onHover: (i: number | null, x: number, y: number) => void;
  onPick: (i: number) => void;
}

export function Scene(p: SceneProps) {
  const { gl } = useThree();
  const dpr = gl.getPixelRatio();
  const commentMat = useMemo(() => contactMaterial(15 * dpr), [dpr]);
  const researchMat = useMemo(() => contactMaterial(20 * dpr), [dpr]);
  const sweepRef = useRef<THREE.Group>(null);

  const geom = useMemo(() => {
    const c = p.points.cols, n = p.points.n;
    const pos = new Float32Array(n * 3), cp = new Float32Array(n), az = new Float32Array(n), size = new Float32Array(n), idx = new Float32Array(n);
    for (let i = 0; i < n; i++) {
      pos[i * 3] = c.x[i]; pos[i * 3 + 1] = c.y[i] * 0.72; pos[i * 3 + 2] = c.z[i];
      cp[i] = c.cp[i]; az[i] = Math.atan2(c.z[i], c.x[i]); idx[i] = i;
      size[i] = 0.8 + Math.min(1.3, Math.sqrt(c.len[i] / 220));
    }
    const g = new THREE.BufferGeometry();
    g.setAttribute("position", new THREE.BufferAttribute(pos, 3));
    g.setAttribute("aCp", new THREE.BufferAttribute(cp, 1));
    g.setAttribute("aAz", new THREE.BufferAttribute(az, 1));
    g.setAttribute("aSize", new THREE.BufferAttribute(size, 1));
    g.setAttribute("aIdx", new THREE.BufferAttribute(idx, 1));
    g.setAttribute("aSel", new THREE.BufferAttribute(new Float32Array(n).fill(1), 1));
    g.computeBoundingSphere();
    return g;
  }, [p.points]);

  useEffect(() => {
    const a = geom.getAttribute("aSel") as THREE.BufferAttribute;
    for (let i = 0; i < p.mask.length; i++) a.setX(i, p.mask[i]);
    a.needsUpdate = true;
  }, [geom, p.mask]);
  useEffect(() => { commentMat.uniforms.uHover.value = p.hover ?? -1; }, [commentMat, p.hover]);

  const research = useMemo(() => {
    const items = p.sources?.research ?? [];
    const n = items.length;
    const pos = new Float32Array(n * 3), cp = new Float32Array(n), az = new Float32Array(n), size = new Float32Array(n), idx = new Float32Array(n);
    items.forEach((it, i) => {
      const a = timeAngle(it.published_at);
      const lane = (it.id % 7) / 7;                         // spread same-day items across the ring's width
      const [x, , z] = polar(R.time + (lane - 0.5) * 0.12, a);
      pos.set([x, (lane - 0.5) * 0.05, z], i * 3);
      cp[i] = it.new ? 2 : 1; az[i] = a; size[i] = it.tier === "T1" ? 1.5 : 1.1; idx[i] = -10;
    });
    const g = new THREE.BufferGeometry();
    g.setAttribute("position", new THREE.BufferAttribute(pos, 3));
    g.setAttribute("aCp", new THREE.BufferAttribute(cp, 1));
    g.setAttribute("aAz", new THREE.BufferAttribute(az, 1));
    g.setAttribute("aSize", new THREE.BufferAttribute(size, 1));
    g.setAttribute("aIdx", new THREE.BufferAttribute(idx, 1));
    g.setAttribute("aSel", new THREE.BufferAttribute(new Float32Array(n).fill(1), 1));
    return g;
  }, [p.sources]);

  useSweep([commentMat, researchMat], p.position, p.fromPosition, p.sweepId, (a) => {
    const g = sweepRef.current;
    if (!g) return;
    g.visible = a != null;
    if (a != null) g.rotation.y = -a;
  });

  const visibleAt = (i: number) => p.mask[i] === 1 && p.points.cols.cp[i] <= p.position;
  const move = (e: ThreeEvent<PointerEvent>) => {
    const hit = e.intersections.find((h) => h.object === e.object && h.index != null && visibleAt(h.index));
    if (hit?.index != null) { e.stopPropagation(); p.onHover(hit.index, e.nativeEvent.clientX, e.nativeEvent.clientY); }
    else p.onHover(null, 0, 0);
  };
  const click = (e: ThreeEvent<MouseEvent>) => {
    const hit = e.intersections.find((h) => h.object === e.object && h.index != null && visibleAt(h.index));
    if (hit?.index != null) { e.stopPropagation(); p.onPick(hit.index); }
  };

  return (
    <>
      <OrbitControls makeDefault enablePan={false} minDistance={2.2} maxDistance={9} autoRotate autoRotateSpeed={0.25}
                     enableDamping dampingFactor={0.08} maxPolarAngle={Math.PI * 0.62} />
      <points geometry={geom} material={commentMat} onPointerMove={move} onPointerOut={() => p.onHover(null, 0, 0)} onClick={click} />
      <points geometry={research} material={researchMat} />
      <Rings sources={p.sources} />
      <group ref={sweepRef} visible={false}><SweepBlade /></group>
    </>
  );
}

/* ------------------------------------------------------------------------------------------- the sweep */
function SweepBlade() {
  const mat = useMemo(() => new THREE.ShaderMaterial({
    transparent: true, depthWrite: false, side: THREE.DoubleSide, blending: THREE.AdditiveBlending,
    vertexShader: "varying vec2 vUv; void main(){ vUv = uv; gl_Position = projectionMatrix * modelViewMatrix * vec4(position,1.0); }",
    fragmentShader: "varying vec2 vUv; void main(){ float a = (1.0 - vUv.x * 0.7) * (1.0 - abs(vUv.y - 0.5) * 2.0); gl_FragColor = vec4(0.18, 0.45, 0.95, 0.32 * a); }",
  }), []);
  return (
    <>
      <mesh material={mat} position={[R.time / 2 + 0.1, 0, 0]}><planeGeometry args={[R.time + 0.2, 1.4]} /></mesh>
      <mesh position={[(R.time + 0.2) / 2, 0, 0]}><boxGeometry args={[R.time + 0.2, 0.004, 0.004]} /><meshBasicMaterial color="#4d94ff" /></mesh>
    </>
  );
}

/* ------------------------------------------------------------------------------------------- source rings */
function ringPoints(r: number, a0 = 0, a1 = TAU, seg = 256) {
  const pts: THREE.Vector3[] = [];
  for (let i = 0; i <= seg; i++) { const a = a0 + ((a1 - a0) * i) / seg; pts.push(new THREE.Vector3(...polar(r, a))); }
  return new THREE.BufferGeometry().setFromPoints(pts);
}

function Rings({ sources }: { sources: SourcesPayload | undefined }) {
  const guides = useMemo(() => [R.study, R.options, R.sales].flatMap((r) => CARS.map((car) => ringPoints(r, ...sector(car), 64))), []);
  const timeRing = useMemo(() => ringPoints(R.time, TIME_START - 0.12, TIME_START + (300 / 360) * TAU, 256), []);

  // study: one radial tick per item, outward = above its own column's average, inward = below (z-score)
  const study = useMemo(() => {
    const list = sources?.study ?? [];
    const v: number[] = [];
    const groups = new Map<string, typeof list>();
    for (const s of list) { const k = s.car; groups.set(k, [...(groups.get(k) ?? []), s]); }
    for (const [car, items] of groups) {
      const [a0, a1] = sector(car);
      items.forEach((s, i) => {
        const a = a0 + ((a1 - a0) * (i + 0.5)) / items.length;
        const z = Math.max(-2.5, Math.min(2.5, s.z ?? 0)) * 0.05;
        v.push(...polar(R.study, a), ...polar(R.study + z, a));
      });
    }
    return new THREE.BufferGeometry().setAttribute("position", new THREE.Float32BufferAttribute(v, 3));
  }, [sources]);

  // options: one dot per equipment option of today's car
  const options = useMemo(() => {
    const v: number[] = [];
    for (const o of sources?.options ?? []) {
      const [a0, a1] = sector(o.car);
      for (let i = 0; i < o.n; i++) v.push(...polar(R.options + ((i % 3) - 1) * 0.018, a0 + ((a1 - a0) * (i + 0.5)) / o.n));
    }
    return new THREE.BufferGeometry().setAttribute("position", new THREE.Float32BufferAttribute(v, 3));
  }, [sources]);

  // sales: one bar per car × market × year; 2030 forecast drawn as an outline
  const bars = useMemo(() => {
    const rows = (sources?.sales ?? []).filter((s) => s.units && s.units > 0);
    const byCar = new Map<string, typeof rows>();
    for (const s of rows) byCar.set(s.car, [...(byCar.get(s.car) ?? []), s]);
    const out: { pos: [number, number, number]; rot: number; h: number; forecast: boolean }[] = [];
    for (const [car, items] of byCar) {
      const [a0, a1] = sector(car);
      items.forEach((s, i) => {
        const a = a0 + ((a1 - a0) * (i + 0.5)) / items.length;
        const h = Math.max(0.01, (s.units! / 120000) * 0.55);
        out.push({ pos: polar(R.sales, a, h / 2), rot: -a, h, forecast: !!s.is_forecast });
      });
    }
    return out;
  }, [sources]);

  const hair = "#ffffff";
  return (
    <group>
      {guides.map((g, i) => <line key={i}><primitive object={g} attach="geometry" /><lineBasicMaterial color={hair} transparent opacity={0.1} /></line>)}
      <line><primitive object={timeRing} attach="geometry" /><lineDashedMaterial color={hair} transparent opacity={0.16} /></line>
      <lineSegments geometry={study}><lineBasicMaterial color="#dfe4ea" transparent opacity={0.55} /></lineSegments>
      <points geometry={options}><pointsMaterial color="#dfe4ea" size={0.012} transparent opacity={0.55} /></points>
      {bars.map((b, i) => (
        <mesh key={i} position={b.pos} rotation={[0, b.rot, 0]}>
          <boxGeometry args={[0.012, b.h, 0.012]} />
          {b.forecast ? <meshBasicMaterial color="#4d94ff" wireframe transparent opacity={0.5} /> : <meshBasicMaterial color="#dfe4ea" transparent opacity={0.75} />}
        </mesh>
      ))}
      {CARS.map((car) => {
        const [a0, a1] = sector(car);
        return (
          <Html key={car} position={polar(R.labels, (a0 + a1) / 2)} center zIndexRange={[10, 0]}>
            <div className="ring-label"><b>{CAR_NAME[car]}</b><span>{car}</span></div>
          </Html>
        );
      })}
      {[["JUL 25", "2025-07-01"], ["JAN 26", "2026-01-31"], ["JUL 26", "2026-07-31"]].map(([t, d]) => (
        <Html key={t} position={polar(R.time + 0.16, timeAngle(d), 0)} center zIndexRange={[10, 0]}>
          <div className="time-label">{t}</div>
        </Html>
      ))}
    </group>
  );
}

