// The scan volume (react-three-fiber). One shader decides, per contact, whether the current sweep has acquired it.
// At rest every contact is white: held contacts (known at the earlier checkpoint) are dots, contacts this sweep
// acquired are rings. Blue is spent only on the sweep itself, the flare as it passes, hover and the locked contact.
// The same rule drives the comments and the dated research on the time ring. Every ring element can be opened.
import { useEffect, useMemo, useRef } from "react";
import { useFrame, useThree, type ThreeEvent } from "@react-three/fiber";
import { Billboard, Html, OrbitControls } from "@react-three/drei";
import * as THREE from "three";
import type { PointsPayload, Selection, SourcesPayload } from "@/lib/types";
import { CARS, CAR_NAME, MARKET_NAME, R, SWEEP_START, TAU, TIME_START, polar, sector, timeAngle } from "./layout";

const VERT = /* glsl */ `
attribute float aCp; attribute float aSel; attribute float aAz; attribute float aSize; attribute float aIdx;
uniform float uCp, uFrom, uSweep, uStart, uScale, uHover, uDim;
varying float vAlpha; varying float vRing; varying float vFlare; varying float vHov;
const float TAU = 6.2831853;
void main() {
  float lo = min(uCp, uFrom), hi = max(uCp, uFrom);
  float d = mod(aAz - uStart + 2.0 * TAU, TAU) / TAU;
  float passed = step(d, uSweep);
  float vis = aCp <= lo ? 1.0 : (aCp <= hi ? (uCp > uFrom ? passed : 1.0 - passed) : 0.0);
  vFlare = (uCp > uFrom && aCp > lo && aCp <= hi) ? passed * exp(-max(uSweep - d, 0.0) * 14.0) : 0.0;
  vRing = abs(aCp - uCp) < 0.5 ? 1.0 : 0.0;          // acquired by the current sweep
  vHov = abs(aIdx - uHover) < 0.5 ? 1.0 : 0.0;
  vec4 mv = modelViewMatrix * vec4(position, 1.0);
  float depth = smoothstep(3.2, 7.5, -mv.z);           // far contacts recede
  vAlpha = vis * mix(uDim, 1.0, aSel) * mix(0.95, 0.4, depth);
  gl_Position = projectionMatrix * mv;
  gl_PointSize = aSize * uScale * (1.0 + vRing * 0.25 + vFlare * 2.0 + vHov * 2.2) / -mv.z;
}`;
const FRAG = /* glsl */ `
varying float vAlpha; varying float vRing; varying float vFlare; varying float vHov;
void main() {
  float r = length(gl_PointCoord - 0.5);
  if (r > 0.5) discard;
  float dot = smoothstep(0.5, 0.3, r);
  float ring = smoothstep(0.5, 0.42, r) * smoothstep(0.24, 0.32, r);
  float a = mix(dot, ring, vRing * (1.0 - vFlare));
  vec3 blue = vec3(0.30, 0.58, 1.0);
  vec3 col = mix(vec3(0.93, 0.95, 0.97), blue, max(vFlare, vHov));
  gl_FragColor = vec4(col, min(1.0, vAlpha + vHov) * a);
}`;

function contactMaterial(scale: number) {
  return new THREE.ShaderMaterial({
    vertexShader: VERT, fragmentShader: FRAG, transparent: true, depthWrite: false,
    uniforms: {
      uCp: { value: 2 }, uFrom: { value: 2 }, uSweep: { value: 1 }, uStart: { value: SWEEP_START },
      uScale: { value: scale }, uHover: { value: -1 }, uDim: { value: 0.06 },
    },
  });
}

function attrGeometry(pos: Float32Array, attrs: Record<string, Float32Array>) {
  const g = new THREE.BufferGeometry();
  g.setAttribute("position", new THREE.BufferAttribute(pos, 3));
  for (const [k, v] of Object.entries(attrs)) g.setAttribute(k, new THREE.BufferAttribute(v, 1));
  g.computeBoundingSphere();
  return g;
}

/* ------------------------------------------------------------------------------------------- sweep clock */
function useSweep(mats: THREE.ShaderMaterial[], position: number, fromPosition: number, sweepId: number, onAngle: (a: number | null) => void) {
  const start = useRef<number | null>(null);
  const reduced = useMemo(() => window.matchMedia?.("(prefers-reduced-motion: reduce)").matches ?? false, []);
  useEffect(() => {
    for (const m of mats) { m.uniforms.uCp.value = position; m.uniforms.uFrom.value = fromPosition; m.uniforms.uSweep.value = reduced ? 1 : 0; }
    start.current = reduced || position === fromPosition ? null : performance.now();
  }, [sweepId]); // eslint-disable-line react-hooks/exhaustive-deps
  useFrame(() => {
    if (start.current == null) { onAngle(null); return; }
    const t = Math.min(1, (performance.now() - start.current) / 2400);
    const e = 1 - Math.pow(1 - t, 3);
    for (const m of mats) m.uniforms.uSweep.value = e;
    onAngle(t < 1 ? SWEEP_START + e * TAU : null);
    if (t >= 1) { start.current = null; for (const m of mats) m.uniforms.uFrom.value = m.uniforms.uCp.value; }
  });
}

/* ------------------------------------------------------------------------------------------- camera fit */
function CameraFit() {
  const { camera, size } = useThree();
  useEffect(() => {
    const cam = camera as THREE.PerspectiveCamera;
    const aspect = size.width / size.height;
    cam.fov = aspect < 1 ? 58 : 40;
    const fit = (R.labels + 0.3) / (Math.tan(THREE.MathUtils.degToRad(cam.fov / 2)) * aspect);
    cam.position.setLength(Math.max(aspect < 1 ? 6 : 5.6, fit));
    cam.updateProjectionMatrix();
  }, [camera, size.width, size.height]);
  return null;
}

/* ------------------------------------------------------------------------------------------- scene */
export interface Hover { title: string; sub?: string; comment?: number; acquiredHere?: boolean; x: number; y: number }

interface SceneProps {
  points: PointsPayload;
  sources: SourcesPayload | undefined;
  mask: Uint8Array;
  position: number; fromPosition: number; sweepId: number;
  hoverComment: number | null;
  locked: [number, number, number] | null;
  onHover: (h: Hover | null) => void;
  onSelect: (s: Selection, at: [number, number, number]) => void;
}

export const studyValue = (s: { scale: string; value: number | null }) =>
  s.value == null ? "" : s.scale === "dist_7" ? `${Math.round(s.value * 100)}% top-2` : `${s.value.toFixed(1)} / 10`;

export function Scene(p: SceneProps) {
  const { gl } = useThree();
  const dpr = gl.getPixelRatio();
  const commentMat = useMemo(() => contactMaterial(15 * dpr), [dpr]);
  const researchMat = useMemo(() => contactMaterial(19 * dpr), [dpr]);
  const sweepRef = useRef<THREE.Group>(null);
  const setCursor = (on: boolean) => { gl.domElement.style.cursor = on ? "pointer" : ""; };

  /* comments */
  const comments = useMemo(() => {
    const c = p.points.cols, n = p.points.n;
    const pos = new Float32Array(n * 3), cp = new Float32Array(n), az = new Float32Array(n), size = new Float32Array(n), idx = new Float32Array(n);
    for (let i = 0; i < n; i++) {
      pos[i * 3] = c.x[i]; pos[i * 3 + 1] = c.y[i] * 0.72; pos[i * 3 + 2] = c.z[i];
      cp[i] = c.cp[i]; az[i] = Math.atan2(c.z[i], c.x[i]); idx[i] = i;
      size[i] = 0.85 + Math.min(0.8, Math.sqrt(c.len[i] / 300));
    }
    return attrGeometry(pos, { aCp: cp, aAz: az, aSize: size, aIdx: idx, aSel: new Float32Array(n).fill(1) });
  }, [p.points]);
  useEffect(() => {
    const a = comments.getAttribute("aSel") as THREE.BufferAttribute;
    for (let i = 0; i < p.mask.length; i++) a.setX(i, p.mask[i]);
    a.needsUpdate = true;
  }, [comments, p.mask]);
  useEffect(() => { commentMat.uniforms.uHover.value = p.hoverComment ?? -1; }, [commentMat, p.hoverComment]);

  /* research on the time ring */
  const research = useMemo(() => {
    const items = p.sources?.research ?? [];
    const n = items.length;
    const pos = new Float32Array(n * 3), cp = new Float32Array(n), az = new Float32Array(n), size = new Float32Array(n), idx = new Float32Array(n);
    items.forEach((it, i) => {
      const a = timeAngle(it.published_at);
      const lane = (it.id % 7) / 7;
      const [x, , z] = polar(R.time + (lane - 0.5) * 0.12, a);
      pos.set([x, (lane - 0.5) * 0.05, z], i * 3);
      cp[i] = it.new ? 2 : 1; az[i] = a; size[i] = it.tier === "T1" ? 1.5 : 1.1; idx[i] = i;
    });
    return { items, geom: attrGeometry(pos, { aCp: cp, aAz: az, aSize: size, aIdx: idx, aSel: new Float32Array(n).fill(1) }) };
  }, [p.sources]);

  useSweep([commentMat, researchMat], p.position, p.fromPosition, p.sweepId, (a) => {
    const g = sweepRef.current;
    if (!g) return;
    g.visible = a != null;
    if (a != null) g.rotation.y = -a;
  });

  /* picking */
  const first = (e: ThreeEvent<PointerEvent | MouseEvent>, ok: (i: number) => boolean) =>
    e.intersections.find((h) => h.object === e.object && h.index != null && ok(h.index))?.index ?? null;
  const commentOk = (i: number) => p.mask[i] === 1 && p.points.cols.cp[i] <= p.position;
  const researchOk = (i: number) => (research.items[i]?.new ? 2 : 1) <= p.position;
  const at = (g: THREE.BufferGeometry, i: number): [number, number, number] => {
    const a = g.getAttribute("position");
    return [a.getX(i), a.getY(i), a.getZ(i)];
  };

  const onComment = {
    onPointerMove: (e: ThreeEvent<PointerEvent>) => {
      const i = first(e, commentOk);
      if (i == null) return;
      e.stopPropagation(); setCursor(true);
      p.onHover({ title: "", comment: i, acquiredHere: p.points.cols.cp[i] === p.position, x: e.nativeEvent.clientX, y: e.nativeEvent.clientY });
    },
    onPointerOut: () => { setCursor(false); p.onHover(null); },
    onClick: (e: ThreeEvent<MouseEvent>) => {
      const i = first(e, commentOk);
      if (i == null) return;
      e.stopPropagation(); p.onSelect({ kind: "comment", id: p.points.cols.id[i] }, at(comments, i));
    },
  };
  const onResearch = {
    onPointerMove: (e: ThreeEvent<PointerEvent>) => {
      const i = first(e, researchOk);
      if (i == null) return;
      e.stopPropagation(); setCursor(true);
      const it = research.items[i];
      p.onHover({ title: it.headline, sub: `Research · ${it.published_at ?? "undated"}`, x: e.nativeEvent.clientX, y: e.nativeEvent.clientY });
    },
    onPointerOut: () => { setCursor(false); p.onHover(null); },
    onClick: (e: ThreeEvent<MouseEvent>) => {
      const i = first(e, researchOk);
      if (i == null) return;
      e.stopPropagation(); p.onSelect({ kind: "research", item: research.items[i] }, at(research.geom, i));
    },
  };

  return (
    <>
      <CameraFit />
      <OrbitControls makeDefault enablePan={false} minDistance={2.2} maxDistance={14} autoRotate autoRotateSpeed={0.22}
                     enableDamping dampingFactor={0.08} maxPolarAngle={Math.PI * 0.62} />
      <points geometry={comments} material={commentMat} {...onComment} />
      <points geometry={research.geom} material={researchMat} {...onResearch} />
      <Rings sources={p.sources} onHover={p.onHover} onSelect={p.onSelect} setCursor={setCursor} />
      <group ref={sweepRef} visible={false}><SweepBlade /></group>
      {p.locked && <Reticle at={p.locked} />}
    </>
  );
}

/* ------------------------------------------------------------------------------------------- sweep + lock */
function SweepBlade() {
  const mat = useMemo(() => new THREE.ShaderMaterial({
    transparent: true, depthWrite: false, side: THREE.DoubleSide, blending: THREE.AdditiveBlending,
    vertexShader: "varying vec2 vUv; void main(){ vUv = uv; gl_Position = projectionMatrix * modelViewMatrix * vec4(position,1.0); }",
    fragmentShader: "varying vec2 vUv; void main(){ float a = (1.0 - vUv.x * 0.7) * (1.0 - abs(vUv.y - 0.5) * 2.0); gl_FragColor = vec4(0.18, 0.45, 0.95, 0.32 * a); }",
  }), []);
  return (
    <>
      <mesh material={mat} position={[R.time / 2 + 0.1, 0, 0]}><planeGeometry args={[R.time + 0.2, 1.4]} /></mesh>
      <mesh position={[(R.time + 0.2) / 2, 0, 0]}><boxGeometry args={[R.time + 0.2, 0.004, 0.004]} /><meshBasicMaterial color="#4d94ff" /></mesh>
    </>
  );
}

function Reticle({ at }: { at: [number, number, number] }) {
  const ref = useRef<THREE.Group>(null);
  useFrame(({ clock }) => { if (ref.current) ref.current.rotation.z = clock.elapsedTime * 0.8; });
  return (
    <Billboard position={at}>
      <group ref={ref}>
        {[0, 1, 2, 3].map((k) => (
          <mesh key={k} rotation={[0, 0, (k * Math.PI) / 2]}>
            <ringGeometry args={[0.045, 0.052, 16, 1, -0.45, 0.9]} />
            <meshBasicMaterial color="#4d94ff" transparent opacity={0.95} depthTest={false} />
          </mesh>
        ))}
      </group>
    </Billboard>
  );
}

/* ------------------------------------------------------------------------------------------- source rings */
function ringPoints(r: number, a0 = 0, a1 = TAU, seg = 256) {
  const pts: THREE.Vector3[] = [];
  for (let i = 0; i <= seg; i++) { const a = a0 + ((a1 - a0) * i) / seg; pts.push(new THREE.Vector3(...polar(r, a))); }
  return new THREE.BufferGeometry().setFromPoints(pts);
}

const RING_BEARING = Math.PI / 2; // the gap between the 1 Series and 5 Series sectors faces the viewer
const RINGS: { r: number; name: string }[] = [
  { r: R.study, name: "Study" }, { r: R.options, name: "Options" }, { r: R.sales, name: "Sales" }, { r: R.time, name: "Research" },
];

function Rings({ sources, onHover, onSelect, setCursor }: {
  sources: SourcesPayload | undefined;
  onHover: (h: Hover | null) => void;
  onSelect: (s: Selection, at: [number, number, number]) => void;
  setCursor: (on: boolean) => void;
}) {
  const lines = useMemo(() => {
    const guide = new THREE.LineBasicMaterial({ color: "#ffffff", transparent: true, opacity: 0.1 });
    const out: THREE.Line[] = [R.study, R.options, R.sales].flatMap((r) => CARS.map((car) => new THREE.Line(ringPoints(r, ...sector(car), 64), guide)));
    const time = new THREE.Line(ringPoints(R.time, TIME_START - 0.12, TIME_START + (300 / 360) * TAU, 360),
      new THREE.LineDashedMaterial({ color: "#ffffff", transparent: true, opacity: 0.22, dashSize: 0.02, gapSize: 0.025 }));
    time.computeLineDistances();
    out.push(time);
    return out;
  }, []);

  // study: a radial tick per item (outward = above this car × market's average item, inward = below); the tip is pickable
  const study = useMemo(() => {
    const list = sources?.study ?? [];
    const byCar = new Map<string, typeof list>();
    for (const s of list) byCar.set(s.car, [...(byCar.get(s.car) ?? []), s]);
    const seg: number[] = [], tips: number[] = [], items: typeof list = [];
    for (const [car, rows] of byCar) {
      const [a0, a1] = sector(car);
      rows.forEach((s, i) => {
        const a = a0 + ((a1 - a0) * (i + 0.5)) / rows.length;
        const tip = polar(R.study + Math.max(-2.5, Math.min(2.5, s.z ?? 0)) * 0.05, a);
        seg.push(...polar(R.study, a), ...tip);
        tips.push(...tip); items.push(s);
      });
    }
    return {
      items,
      lines: new THREE.BufferGeometry().setAttribute("position", new THREE.Float32BufferAttribute(seg, 3)),
      tips: new THREE.BufferGeometry().setAttribute("position", new THREE.Float32BufferAttribute(tips, 3)),
    };
  }, [sources]);

  // options: one dot per equipment option of today's car
  const options = useMemo(() => {
    const list = sources?.options ?? [];
    const byCar = new Map<string, typeof list>();
    for (const o of list) byCar.set(o.car, [...(byCar.get(o.car) ?? []), o]);
    const v: number[] = [], items: typeof list = [];
    for (const [car, rows] of byCar) {
      const [a0, a1] = sector(car);
      rows.forEach((o, i) => { v.push(...polar(R.options + ((i % 3) - 1) * 0.018, a0 + ((a1 - a0) * (i + 0.5)) / rows.length)); items.push(o); });
    }
    return { items, geom: new THREE.BufferGeometry().setAttribute("position", new THREE.Float32BufferAttribute(v, 3)) };
  }, [sources]);

  // sales: one bar per car × market × year; the 2030 forecast is an outline
  const bars = useMemo(() => {
    const rows = (sources?.sales ?? []).filter((s) => s.units && s.units > 0);
    const byCar = new Map<string, typeof rows>();
    for (const s of rows) byCar.set(s.car, [...(byCar.get(s.car) ?? []), s]);
    const out: { row: (typeof rows)[number]; pos: [number, number, number]; rot: number; h: number }[] = [];
    for (const [car, items] of byCar) {
      const [a0, a1] = sector(car);
      items.forEach((s, i) => {
        const a = a0 + ((a1 - a0) * (i + 0.5)) / items.length;
        const h = Math.max(0.01, (s.units! / 120000) * 0.3);
        out.push({ row: s, pos: polar(R.sales, a, h / 2), rot: -a, h });
      });
    }
    return out;
  }, [sources]);

  const pick = (e: ThreeEvent<PointerEvent | MouseEvent>) =>
    e.intersections.find((h) => h.object === e.object && h.index != null)?.index ?? null;
  const pos = (g: THREE.BufferGeometry, i: number): [number, number, number] => {
    const a = g.getAttribute("position");
    return [a.getX(i), a.getY(i), a.getZ(i)];
  };
  const hover = (e: ThreeEvent<PointerEvent>, title: string, sub: string) => {
    e.stopPropagation(); setCursor(true); onHover({ title, sub, x: e.nativeEvent.clientX, y: e.nativeEvent.clientY });
  };
  const out = () => { setCursor(false); onHover(null); };

  return (
    <group>
      {lines.map((l, i) => <primitive key={i} object={l} />)}
      <lineSegments geometry={study.lines}><lineBasicMaterial color="#dfe4ea" transparent opacity={0.55} /></lineSegments>
      <points geometry={study.tips}
              onPointerMove={(e) => { const i = pick(e); if (i != null) { const s = study.items[i]; hover(e, s.item, `Study · ${CAR_NAME[s.car]} · ${MARKET_NAME[s.market]} · ${studyValue(s)}`); } }}
              onPointerOut={out}
              onClick={(e) => { const i = pick(e); if (i != null) { e.stopPropagation(); onSelect({ kind: "study", item: study.items[i] }, pos(study.tips, i)); } }}>
        <pointsMaterial color="#dfe4ea" size={0.016} transparent opacity={0.8} />
      </points>
      <points geometry={options.geom}
              onPointerMove={(e) => { const i = pick(e); if (i != null) { const o = options.items[i]; hover(e, o.name ?? o.code ?? "Option", `Option · ${CAR_NAME[o.car]} · ${o.availability ?? ""}`); } }}
              onPointerOut={out}
              onClick={(e) => { const i = pick(e); if (i != null) { e.stopPropagation(); onSelect({ kind: "option", item: options.items[i] }, pos(options.geom, i)); } }}>
        <pointsMaterial color="#dfe4ea" size={0.013} transparent opacity={0.6} />
      </points>
      {bars.map((b, i) => (
        <mesh key={i} position={b.pos} rotation={[0, b.rot, 0]}
              onPointerMove={(e) => hover(e, `${(b.row.units ?? 0).toLocaleString("en-US")} cars`, `Sales · ${CAR_NAME[b.row.car]} · ${MARKET_NAME[b.row.market]} · ${b.row.year}${b.row.is_forecast ? " forecast" : ""}`)}
              onPointerOut={out}
              onClick={(e) => { e.stopPropagation(); onSelect({ kind: "sales", item: b.row }, [b.pos[0], b.h, b.pos[2]]); }}>
          <boxGeometry args={[0.014, b.h, 0.014]} />
          {b.row.is_forecast ? <meshBasicMaterial color="#dfe4ea" wireframe transparent opacity={0.35} /> : <meshBasicMaterial color="#dfe4ea" transparent opacity={0.45} />}
        </mesh>
      ))}
      {RINGS.map((g) => (
        <Html key={g.name} position={polar(g.r, RING_BEARING, 0.02)} center zIndexRange={[10, 0]}>
          <div className="ring-name">{g.name}</div>
        </Html>
      ))}
      {CARS.map((car) => {
        const [a0, a1] = sector(car);
        return (
          <Html key={car} position={polar(R.labels + 0.15, (a0 + a1) / 2, 0.22)} center zIndexRange={[10, 0]}>
            <div className="ring-label"><b>{CAR_NAME[car]}</b><span>{car}</span></div>
          </Html>
        );
      })}
      {[["JUL 25", "2025-07-01"], ["JAN 26", "2026-01-31"], ["JUL 26", "2026-07-31"]].map(([t, d]) => (
        <Html key={t} position={polar(R.time - 0.2, timeAngle(d), -0.04)} center zIndexRange={[10, 0]}>
          <div className="time-label">{t}</div>
        </Html>
      ))}
    </group>
  );
}

// Scan: every raw piece of evidence the system holds, at the current checkpoint, as one 3D space.
import { Suspense, useEffect, useMemo, useState } from "react";
import { Canvas } from "@react-three/fiber";
import { useQuery } from "@tanstack/react-query";
import { ExternalLink, X } from "lucide-react";
import { api } from "@/lib/api";
import type { Comment, PointsPayload, Selection, SourcesPayload } from "@/lib/types";
import { useCheckpoint } from "@/state/checkpoint";
import { Scene, studyValue, type Hover } from "./Scene";
import { CAR_NAME, MARKET_NAME } from "./layout";
import "./scan.css";

const fmt = (n: number | undefined | null) => (n == null ? "–" : n.toLocaleString("en-US"));

type Dim = "car" | "market" | "channel" | "type" | "engine";
const DIMS: { id: Dim; name: string }[] = [
  { id: "car", name: "Car" }, { id: "market", name: "Market" }, { id: "channel", name: "Channel" },
  { id: "type", name: "Label" }, { id: "engine", name: "Engine" },
];
function valueName(dim: Dim, v: string | null): string {
  if (v == null) return "Unlabelled";
  if (dim === "car") return CAR_NAME[v] ?? v;
  if (dim === "market") return MARKET_NAME[v] ?? v;
  return v;
}

export function Scan() {
  const { from, sweepId, position, checkpoints } = useCheckpoint();
  const points = useQuery({ queryKey: ["scan", "points"], queryFn: () => api.get<PointsPayload>("/api/scan/points"), staleTime: Infinity });
  const sources = useQuery({ queryKey: ["scan", "sources"], queryFn: () => api.get<SourcesPayload>("/api/scan/sources?cp=cp2"), staleTime: Infinity });
  const [dim, setDim] = useState<Dim>("car");
  const [isolate, setIsolate] = useState<Set<number>>(new Set());
  const [hover, setHover] = useState<Hover | null>(null);
  const [selected, setSelected] = useState<{ sel: Selection; at: [number, number, number] } | null>(null);
  const fromPosition = checkpoints?.find((c) => c.id === from)?.position ?? position;

  const mask = useMemo(() => {
    const n = points.data?.n ?? 0;
    const m = new Uint8Array(n).fill(1);
    if (!points.data || isolate.size === 0) return m;
    const col = points.data.cols[dim];
    for (let i = 0; i < n; i++) m[i] = isolate.has(col[i]) ? 1 : 0;
    return m;
  }, [points.data, dim, isolate]);

  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (e.key !== "Escape") return;
      if (selected) setSelected(null); else setIsolate(new Set());
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [selected]);

  return (
    <main className="scan" aria-label="Raw evidence at the selected checkpoint">
      <div className="scan-canvas">
        {points.data && (
          <Canvas dpr={[1, 2]} camera={{ position: [0, 2.3, 5.3], fov: 40, near: 0.05, far: 60 }}
                  raycaster={{ params: { Points: { threshold: 0.018 }, Line: { threshold: 0 }, Mesh: {}, LOD: {}, Sprite: {} } }}
                  gl={{ antialias: true, alpha: false }} onCreated={({ gl }) => gl.setClearColor("#000000")}
                  onPointerMissed={() => setSelected(null)}>
            <Suspense fallback={null}>
              <Scene points={points.data} sources={sources.data} mask={mask} position={position} fromPosition={fromPosition}
                     sweepId={sweepId} hoverComment={hover?.comment ?? null} locked={selected?.at ?? null}
                     onHover={setHover} onSelect={(sel, at) => { setSelected({ sel, at }); setHover(null); }} />
            </Suspense>
          </Canvas>
        )}
        {points.isPending && <div className="scan-state"><span className="scan-pulse" aria-hidden />Scanning</div>}
        {points.isError && <div className="scan-state error">{(points.error as Error).message}</div>}
      </div>

      <Readout />

      {points.data && (
        <Key points={points.data} position={position} dim={dim} isolate={isolate}
             onDim={(d) => { setDim(d); setIsolate(new Set()); }}
             onToggle={(v) => setIsolate((s) => { const n = new Set(s); n.has(v) ? n.delete(v) : n.add(v); return n; })}
             onClear={() => setIsolate(new Set())} />
      )}

      {hover && !selected && <HoverCard hover={hover} points={points.data} />}
      {selected && <Inspector sel={selected.sel} sales={sources.data?.sales ?? []} onClose={() => setSelected(null)}
                              cpLabel={(id) => checkpoints?.find((c) => c.id === id)?.label ?? id} />}
    </main>
  );
}

/* ------------------------------------------------------------------------------------------- glyphs */
type GlyphKind = "comment" | "study" | "option" | "sales" | "research";
function Glyph({ kind }: { kind: GlyphKind }) {
  const c = "currentColor";
  return (
    <svg width="14" height="14" viewBox="0 0 14 14" aria-hidden className="glyph">
      {kind === "comment" && <><circle cx="4" cy="6" r="1.6" fill={c} /><circle cx="9.5" cy="4" r="1.6" fill="none" stroke={c} /><circle cx="8.5" cy="10" r="1.4" fill={c} /></>}
      {kind === "study" && <><path d="M2 8h10" stroke={c} strokeOpacity=".35" /><path d="M4 8V4M7 8v4M10 8V3" stroke={c} strokeWidth="1.3" /></>}
      {kind === "option" && <>{[2.5, 5.5, 8.5, 11.5].map((x) => <circle key={x} cx={x} cy="7" r="1" fill={c} />)}</>}
      {kind === "sales" && <><rect x="2.5" y="6" width="2" height="6" fill={c} /><rect x="6" y="3" width="2" height="9" fill={c} /><rect x="9.5" y="2.5" width="2" height="9.5" fill="none" stroke={c} /></>}
      {kind === "research" && <><path d="M1.5 9.5a6 6 0 0 1 11 0" fill="none" stroke={c} strokeDasharray="1.5 1.5" /><circle cx="7" cy="4.2" r="1.4" fill={c} /></>}
    </svg>
  );
}

/* ------------------------------------------------------------------------------------------- readout */
function Readout() {
  const { current, position } = useCheckpoint();
  const s = current?.sources;
  const plus = (n: number | undefined) => (position > 1 && n ? <span className="plus">+{fmt(n)}</span> : null);
  const internal = s ? s.study.visible + s.option_list.visible + s.sales.visible : undefined;
  const cells: { k: GlyphKind; label: string; n: number | undefined; nu?: number }[] = [
    { k: "comment", label: "Comments", n: s?.feedback.visible, nu: s?.feedback.new },
    { k: "research", label: "Research", n: s?.research.visible, nu: s?.research.new },
    { k: "sales", label: "BMW data", n: internal },
  ];
  return (
    <dl className="readout" aria-label="Evidence at this checkpoint">
      {cells.map((c) => (
        <div key={c.label}>
          <dt><Glyph kind={c.k} /><span className="label">{c.label}</span></dt>
          <dd><span className="num">{fmt(c.n)}</span>{plus(c.nu)}</dd>
        </div>
      ))}
    </dl>
  );
}

/* ------------------------------------------------------------------------------------------- key */
function Key(p: { points: PointsPayload; position: number; dim: Dim; isolate: Set<number>; onDim: (d: Dim) => void; onToggle: (v: number) => void; onClear: () => void }) {
  const values = p.points.dict[p.dim] as (string | null)[];
  const counts = useMemo(() => {
    const col = p.points.cols[p.dim], cps = p.points.cols.cp;
    const vis = new Array(values.length).fill(0);
    for (let i = 0; i < col.length; i++) if (col[i] >= 0 && cps[i] <= p.position) vis[col[i]]++;
    return vis as number[];
  }, [p.points, p.dim, p.position, values.length]);
  const max = Math.max(1, ...counts);
  return (
    <nav className="key" aria-label="Filter comments">
      <div className="key-dims" role="tablist">
        {DIMS.map((d) => <button key={d.id} role="tab" aria-selected={p.dim === d.id} onClick={() => p.onDim(d.id)}>{d.name}</button>)}
      </div>
      <ul className="key-values">
        {values.map((v, i) => {
          const n = counts[i];
          if (!n) return null;
          const on = p.isolate.size === 0 || p.isolate.has(i);
          return (
            <li key={i}>
              <button aria-pressed={p.isolate.has(i)} data-dim={on ? undefined : ""} onClick={() => p.onToggle(i)}>
                <span className="key-name">{valueName(p.dim, v)}</span>
                <span className="key-bar" aria-hidden><span style={{ transform: `scaleX(${n / max})` }} /></span>
                <span className="key-n">{fmt(n)}</span>
              </button>
            </li>
          );
        })}
      </ul>
      {p.isolate.size > 0 && <button className="key-clear" onClick={p.onClear}>Show all <span className="label">Esc</span></button>}
    </nav>
  );
}

/* ------------------------------------------------------------------------------------------- hover */
const useComment = (id: number | null) =>
  useQuery({ queryKey: ["comment", id], queryFn: () => api.get<Comment>(`/api/scan/comment/${id}`), staleTime: Infinity, enabled: id != null });

function HoverCard({ hover, points }: { hover: Hover; points: PointsPayload | undefined }) {
  const id = hover.comment != null && points ? points.cols.id[hover.comment] : null;
  const q = useComment(id);
  const left = Math.min(hover.x + 16, window.innerWidth - 336), top = Math.min(hover.y + 16, window.innerHeight - 140);
  return (
    <div className="hovercard" style={{ left, top }} role="tooltip">
      {id != null ? (
        <>
          <p>{q.data?.text ?? " "}</p>
          {q.data && (
            <div className="hovercard-meta">
              <i className={`mark ${hover.acquiredHere ? "new" : "held"}`} aria-hidden />
              <span>{CAR_NAME[q.data.car] ?? q.data.car}</span><span>{q.data.country}</span><span>{q.data.channel}</span>
            </div>
          )}
        </>
      ) : (
        <>
          <p>{hover.title}</p>
          {hover.sub && <div className="hovercard-meta"><span>{hover.sub}</span></div>}
        </>
      )}
    </div>
  );
}

/* ------------------------------------------------------------------------------------------- inspector */
const LAYER: Record<Selection["kind"], { name: string; what: string; glyph: GlyphKind }> = {
  comment: { name: "Customer comment", what: "Placed by meaning: comments that say similar things sit close together. Not classified yet.", glyph: "comment" },
  study: { name: "Customer study 2025", what: "Tick length: how far this topic is rated above or below this car's average.", glyph: "study" },
  option: { name: "Equipment option", what: "Today's car, from the German price list.", glyph: "option" },
  sales: { name: "BMW sales volume", what: "BMW-internal figures, stylized (Q-015). Outline = 2030 forecast.", glyph: "sales" },
  research: { name: "Web research", what: "Cited source, placed on the outer ring by publication date.", glyph: "research" },
};

function Inspector({ sel, sales, onClose, cpLabel }: { sel: Selection; sales: SourcesPayload["sales"]; onClose: () => void; cpLabel: (id: string) => string }) {
  const L = LAYER[sel.kind];
  return (
    <aside className="sheet" aria-label={L.name}>
      <button className="sheet-close" onClick={onClose} aria-label="Close"><X size={16} /></button>
      <header className="sheet-head">
        <span className="sheet-layer"><Glyph kind={L.glyph} />{L.name}</span>
        <p className="sheet-what">{L.what}</p>
      </header>
      {sel.kind === "comment" && <CommentBody id={sel.id} cpLabel={cpLabel} />}
      {sel.kind === "study" && <StudyBody s={sel.item} />}
      {sel.kind === "option" && (
        <>
          <h2 className="sheet-title">{sel.item.name ?? sel.item.code}</h2>
          <Facts rows={[["Car", CAR_NAME[sel.item.car] ?? sel.item.car], ["Category", sel.item.category], ["Availability", sel.item.availability],
                        ["Package", sel.item.package], ["Option code", sel.item.code]]} />
        </>
      )}
      {sel.kind === "sales" && <SalesBody row={sel.item} all={sales} />}
      {sel.kind === "research" && (
        <>
          <h2 className="sheet-title">{sel.item.headline}</h2>
          {(sel.item.value != null || sel.item.yoy != null) && (
            <div className="sheet-figure">
              {sel.item.value != null && <span className="num">{sel.item.value.toLocaleString("en-US")}{sel.item.unit === "pct" ? "%" : ""}</span>}
              {sel.item.yoy != null && <span className="sheet-yoy">{sel.item.yoy > 0 ? "+" : ""}{sel.item.yoy}% YoY</span>}
            </div>
          )}
          <Facts rows={[["Published", sel.item.published_at ?? "undated"], ["Known from", sel.item.new ? "JUL 26" : "JAN 26"],
                        ["About", sel.item.entity], ["Region", sel.item.region], ["Trust", sel.item.tier]]} />
          {sel.item.url && <a className="sheet-link" href={sel.item.url} target="_blank" rel="noreferrer">Open source <ExternalLink size={13} /></a>}
        </>
      )}
    </aside>
  );
}

function Facts({ rows }: { rows: [string, string | null | undefined][] }) {
  return (
    <dl className="sheet-facts">
      {rows.filter(([, v]) => v).map(([k, v]) => <div key={k}><dt className="label">{k}</dt><dd>{v}</dd></div>)}
    </dl>
  );
}

function CommentBody({ id, cpLabel }: { id: number; cpLabel: (id: string) => string }) {
  const q = useComment(id);
  const c = q.data;
  if (!c) return <div className="sheet-skel" aria-hidden><span /><span /><span /></div>;
  const label = c.bmw_labels?.[0];
  return (
    <>
      <blockquote className="sheet-quote">{c.text}</blockquote>
      <Facts rows={[["Car", CAR_NAME[c.car] ?? c.car],
                    ["Market", `${MARKET_NAME[c.market] ?? c.market}${c.country && c.country !== c.market ? ` · ${c.country}` : ""}`],
                    ["Channel", c.channel], ["Engine", c.engine],
                    ["BMW label", `${label?.feedback_type ?? "Unlabelled"}${label?.vfc_level2 && label.vfc_level2 !== "no_class_found" ? ` · ${label.vfc_level2}` : ""}`],
                    ["Acquired", cpLabel(c.checkpoint)], ["ID", c.external_id]]} />
    </>
  );
}

function StudyBody({ s }: { s: Extract<Selection, { kind: "study" }>["item"] }) {
  const z = Math.max(-2.5, Math.min(2.5, s.z ?? 0));
  return (
    <>
      <h2 className="sheet-title">{s.item}</h2>
      <div className="sheet-figure"><span className="num">{studyValue(s)}</span></div>
      <div className="zbar" role="img" aria-label={`${z >= 0 ? "Above" : "Below"} this car's average by ${Math.abs(z).toFixed(1)} standard deviations`}>
        <span className="zbar-mid" />
        <span className="zbar-fill" style={{ left: z >= 0 ? "50%" : `${50 + (z / 2.5) * 50}%`, width: `${(Math.abs(z) / 2.5) * 50}%` }} />
        <span className="zbar-l label">below average</span><span className="zbar-r label">above average</span>
      </div>
      <Facts rows={[["Car", CAR_NAME[s.car] ?? s.car], ["Market", MARKET_NAME[s.market] ?? s.market],
                    ["Scale", s.scale === "dist_7" ? "7-point, share of top two answers" : "Mean rating, 0–10"]]} />
    </>
  );
}

function SalesBody({ row, all }: { row: Extract<Selection, { kind: "sales" }>["item"]; all: SourcesPayload["sales"] }) {
  const series = all.filter((s) => s.car === row.car && s.market === row.market).sort((a, b) => a.year - b.year);
  const max = Math.max(1, ...series.map((s) => s.units ?? 0));
  return (
    <>
      <h2 className="sheet-title">{CAR_NAME[row.car] ?? row.car} · {MARKET_NAME[row.market] ?? row.market}</h2>
      <div className="minibars" role="img" aria-label="Sales by year">
        {series.map((s) => (
          <div key={s.year} className="minibar" data-on={s.year === row.year ? "" : undefined} data-forecast={s.is_forecast ? "" : undefined}>
            <span className="minibar-n">{fmt(s.units)}</span>
            <span className="minibar-col"><span style={{ transform: `scaleY(${(s.units ?? 0) / max})` }} /></span>
            <span className="label">{s.year}{s.is_forecast ? " fc" : ""}</span>
          </div>
        ))}
      </div>
    </>
  );
}

